var OA={"ask_first.host_rule"({name:e,rules:n}){return`A permission rule of this session (${n}) asks before it uses ${e}'s tools.`},"ask_first.host_rule.cannot_ask"({name:e,rules:n}){return`The rule ${n} asks before this session uses ${e}, and this context cannot ask.`},"plan_mode.entered_while_asking"(e){return`This session entered plan mode while the approval was pending; a state-changing ${e} call is not approved from plan mode.`},host_unresponsive({name:e,checks:n,intervalMs:t,whileRunning:r}){return`${e} stopped answering ${r?"while this command was running":"after this command was sent to it"} (${n} checks about ${Math.round(t/1000)} s apart went unanswered). Its state is unknown \u2014 it may have completed, failed, ${r?"or still be running":"never started, or still be running"}. Do not retry non-idempotent commands on ${e} until ${e} reconnects; continue with work that doesn't need it and say what you could not verify.`},"unverified_refusal.call_phase"({name:e,whileRunning:n}){return`A reply that could not be verified says this session is no longer paired with ${e}. ${n?"It was running there; whether it finished is unknown.":"The state of this command there is unknown \u2014 it may or may not have run."} Do not retry it on ${e} until ${e} re-announces; continue with what you can do without it, and tell the user you could not confirm whether it ${n?"finished":"ran"}.`},approval_no_longer_covers(e){return`A permission rule changed while this was waiting; nothing ran on ${e}. Ask again to get a fresh approval.`},"in_progress.checkin"(e){return`Checking on ${e} \u2014 the call is still with it\u2026`},"card.standing_unavailable"({name:e,kind:n}){return`Always allow isn\u2019t available for ${n==="command"?"commands run":"files"} on ${e} yet \u2014 this approves once.`},no_answer({name:e,afterMs:n}){return`No one approved or denied this within ${Math.round(n/1000)} s, so it was not run on ${e}. Nothing changed there. Continue with work that doesn't need this command and tell the user what you skipped; if it is essential, ask them directly.`},"ask_ended.notice"({name:e,toolName:n,reason:t,afterMs:r}){return`The approval for ${n} on ${e} was withdrawn \u2014 ${s(e,n,t,r)}; nothing was run.`},withdrawn({name:e,reason:n}){return`The request to run this on ${e} was withdrawn \u2014 ${i(e,n)}; nothing ran there. Ask the user how to proceed rather than retrying.`}};function s(e,n,t,r){switch(t){case"no_answer":return`nobody answered within ${o(r)}`;case"host_withdrawn":return`${e} disconnected`;case"superseded":return`Claude Code on ${e} restarted`;case"evicted":return`${e} had too many approvals waiting`;case"tool_withdrawn":return`${e} stopped offering ${n}`;case"host_unbound":return`${e} is no longer available to this session`;case"host_stopped":return`Claude Code on ${e} quit`;case"stale_answer":return`the answer reached ${e} too late`;case"record_evicted":return`${e} no longer had a record of it`;case"replaced_by_retry":return"a newer copy of the request replaced it";case"unrecognized":return`${e} ended it`}}function o(e){let n=Math.round(e/1000);return n>=60&&n%60===0?`${n/60} min`:`${n} s`}function i(e,n){switch(n){case"no_answer":return"no one answered it in time";case"host_withdrawn":return`Claude Code on ${e} left the session`;case"superseded":return`a newer Claude Code on ${e} took over from the one that asked`;case"evicted":return`too many requests were already waiting on ${e}`;case"tool_withdrawn":return`${e} stopped serving this tool`;case"host_unbound":return`${e} is no longer bound to this session`;case"host_stopped":return`Claude Code on ${e} was shutting down`;case"stale_answer":return`an answer was given but reached ${e} too late to count`;case"record_evicted":return`${e} no longer had a record of it`;case"replaced_by_retry":return"a newer copy of this request now carries the question";case"unrecognized":return`${e} let it go for a reason this build does not know`}}
export{OA};
